raw:
{
  "spells": [
    {
      "id": "spell_faith_04",
      "theory": "誓约见证将少量魔力送入誓词所用的绳结或刻痕，使立誓的事实留存在媒介表面。绳结、木片或石面都可以承载，但表面太滑时就难以附着。见证只记下谁在何时自愿说出哪句承诺，不改变立誓者的心意，也不阻止背誓。媒介被毁时记录随之消散，因此乡约常把绳结收在干燥处。",
      "casting": "让立誓者双手握住绳结，施术者以指尖沿绳股缓慢送入魔力，同时听清誓词。誓词说完后停手，绳结上会浮出浅痕。",
      "failure": "若誓词被外力打断或施术者中途松手，浅痕只出现半截，随后褪去。绳结可能发烫片刻，使握持者松手，但不会灼伤皮肤。",
      "counters": [
        "在誓词说完前抽走绳结，使魔力无处附着。",
        "事后用刀刮去绳结表面的浅痕，记录便无法辨认。"
      ],
      "socialConsequences": "河谷乡约常请人见证婚约、田界和借贷承诺，因为留下痕迹后争执时有据可查。不愿留痕的人会被视为心里有鬼，但拒绝见证并不违法。城里的公会文书有时嫌弃绳结粗糙，更愿意用纸契；港口的船长则担心绳结受潮，宁愿多备一条干绳。见证者若私自刮痕，会被乡邻指责。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时浅痕歪斜，只能辨出大致轮廓。",
        "熟练者能让浅痕整齐，清楚对应誓词首尾。",
        "熟练者可在绳结受潮时仍留下可辨痕迹。",
        "更高熟练度使痕迹保存更久，仍不强迫守誓。"
      ]
    },
    {
      "id": "spell_faith_05",
      "theory": "慈息术把魔力化为细缓暖流，沿信众自愿伸出的伤处表面移动，促使浅层伤口收拢。暖流只作用于破皮和淤肿，对断骨、内伤与失血没有用处。仪式需要受术者清醒同意，并保持伤处暴露。魔力走完后暖流即散，伤口仍需洁净包扎，否则会重新恶化。",
      "casting": "施术者以清水沾湿指尖，在伤处外缘画一个不闭合的弧，然后缓慢送入魔力，直到暖流走完一圈。受术者须保持不动。",
      "failure": "魔力送入太快时暖流会缩成一点，伤处只热一下便凉，伤口没有收拢。若受术者中途抽回手臂，弧线断开，暖流反冲使施术者指尖发麻片刻。",
      "counters": [
        "在弧线画成前移开伤处，使暖流失去依附。",
        "用湿布盖住伤处，隔断魔力与皮肤的接触。"
      ],
      "socialConsequences": "教会看护者常用此术处理信众的擦伤和烫伤，但坚持先问对方是否愿意。码头搬运工觉得它比草药快，却也有人嫌仪式麻烦，宁可自己包扎。药铺师傅担心浅伤病人都去找教会，影响草药生意，但重伤者仍会送到药铺。若施术者未经同意就伸手，会被信众告到乡约，视为侵犯。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时暖流断断续续，伤口收拢很慢。",
        "熟练者能让暖流均匀，浅伤收口更整齐。",
        "熟练者可控制暖流范围，不波及伤口周围。",
        "更高熟练度使暖流稳定，仍只处理浅层伤口。"
      ]
    },
    {
      "id": "spell_faith_06",
      "theory": "渡魂慰语以低缓魔力振动安抚悲恸者的呼吸，并让施术者辨出附近低阶游魂的微弱扰动。游魂只是残留的冷意和模糊轮廓，不能回答问题，也不能被驱使。慰语对活人的作用仅限于缓和哭泣与颤抖，不能治愈疯癫或消除记忆。范围外的游魂不会被引过来，施术者也不能借此与死者对话。",
      "casting": "施术者盘坐，双手交叠按在胸前，以缓慢的吐息送出魔力，同时低声念诵固定的慰语。悲恸者需在近处静坐。",
      "failure": "吐息紊乱时魔力会散成几缕，悲恸者只感到一阵凉意，游魂的轮廓反而更模糊。若施术者情绪激动，慰语可能变成呛咳，使在场者受惊。",
      "counters": [
        "让悲恸者离开范围，慰语便失去安抚对象。",
        "用浓烈香料熏屋，气味可掩盖游魂的冷意扰动。"
      ],
      "socialConsequences": "河谷人家在丧事后请人慰语，认为能让生者好过些，但不指望见到死者。城里公会成员觉得这术不够体面，宁愿请医师开安神药。港口水手失踪后，家属会请人辨游魂，但港务规定不得据此索赔，只作安慰。若施术者宣称能复活死者，会被乡约和港务同时追究欺诈。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时慰语时断时续，安抚效果短暂。",
        "熟练者能让悲恸者呼吸逐渐平稳，游魂轮廓稍清。",
        "熟练者可在嘈杂处维持慰语，仍不引动游魂。",
        "更高熟练度使辨魂更准，仍不能与死者交谈。"
      ]
    }
  ]
}
